package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.Rect;import android.text.Layout;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import org.json.*;import org.junit.Test;import static org.junit.Assert.*;import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
/** Disposable emulator audit: actual layouts at 130%, not product-time listeners. */
@androidx.media3.common.util.UnstableApi
public class ScreenLayoutReviewTest {
 private static final class BitmapCapture {static void capture(Instrumentation ins,Context c,String name)throws Exception{android.graphics.Bitmap b=ins.getUiAutomation().takeScreenshot();if(b==null)return;try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"audit-"+name+".png"))){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}finally{b.recycle();}}}
 private final Instrumentation ins=getInstrumentation();
 private String shell(String command)throws Exception{try(InputStream in=new android.os.ParcelFileDescriptor.AutoCloseInputStream(ins.getUiAutomation().executeShellCommand(command));ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8").trim();}}
 private ScrollView scroll(View view){if(view instanceof ScrollView)return (ScrollView)view;if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++){ScrollView found=scroll(((ViewGroup)view).getChildAt(i));if(found!=null)return found;}return null;}
 private boolean scrolling(View v){for(android.view.ViewParent p=v.getParent();p instanceof View;p=p.getParent())if(p instanceof ScrollView||p instanceof HorizontalScrollView||p instanceof android.widget.AbsListView||p instanceof android.webkit.WebView)return true;return false;}
 private void inspect(Activity screen,View view,List<String> problems){
  if(view instanceof android.webkit.WebView)return;
  if(view instanceof TextView&&view.isShown()){
   TextView t=(TextView)view;Layout l=t.getLayout();String value=t.getText().toString();
   if(l!=null&&!value.isEmpty()&&t.getWidth()>0&&t.getHeight()>0){
    String label=screen.getClass().getSimpleName()+": "+value.replace('\n',' ').substring(0,Math.min(75,value.length()));
    int h=t.getHeight()-t.getCompoundPaddingTop()-t.getCompoundPaddingBottom(),w=t.getWidth()-t.getCompoundPaddingLeft()-t.getCompoundPaddingRight();Rect visible=new Rect();boolean shown=t.getGlobalVisibleRect(visible);
    if(shown&&visible.height()>=t.getHeight()-2&&h+3<l.getHeight())problems.add(label+" VERTICAL text="+l.getHeight()+" available="+h);
    if((t instanceof Button||t.getParent() instanceof Spinner)&&shown){for(int i=0;i<l.getLineCount();i++)if(l.getLineWidth(i)>w+3||l.getEllipsisCount(i)>0){problems.add(label+" BUTTON_WIDTH text="+l.getLineWidth(i)+" available="+w);break;}}
    if(!scrolling(t)&&t.isClickable()&&t.isEnabled()){Rect own=new Rect();int[] xy=new int[2];t.getLocationOnScreen(xy);own.set(xy[0],xy[1],xy[0]+t.getWidth(),xy[1]+t.getHeight());Rect frame=new Rect();screen.getWindow().getDecorView().getWindowVisibleDisplayFrame(frame);if(!frame.contains(own))problems.add(label+" OUTSIDE_WINDOW "+own.toShortString()+" frame="+frame.toShortString());}
    if(shown&&t.getParent() instanceof LinearLayout&&((LinearLayout)t.getParent()).getOrientation()==LinearLayout.HORIZONTAL){ViewGroup parent=(ViewGroup)t.getParent();if(t.getRight()>parent.getWidth()-parent.getPaddingRight()+2||t.getLeft()<parent.getPaddingLeft()-2)problems.add(label+" OUTSIDE_ROW right="+t.getRight()+" row="+parent.getWidth());}
   }
  }
  if(view instanceof ViewGroup)for(int i=0;i<((ViewGroup)view).getChildCount();i++)inspect(screen,((ViewGroup)view).getChildAt(i),problems);
 }
 @Test public void primaryScreensHaveReadableControlsAndScrollableFormsAtLargeFont()throws Exception{review(false);}
 @Test public void narrowScreensKeepFullLabelsAndNavigationReachable()throws Exception{review(true);}
 private String override(String current,String label){java.util.regex.Matcher match=java.util.regex.Pattern.compile("Override "+label+": ([^\\r\\n]+)").matcher(current);return match.find()?match.group(1).trim():"reset";}
 private void review(boolean narrow)throws Exception{
  Context c=ins.getTargetContext();assertTrue("Only run on an emulator",shell("getprop ro.kernel.qemu").equals("1")||shell("getprop ro.boot.qemu").equals("1"));String oldSize=override(shell("wm size"),"size"),oldDensity=override(shell("wm density"),"density"),oldFont=shell("settings get system font_scale");SharedPreferences dj=c.getSharedPreferences("dj",0);boolean hadMode=dj.contains("mode"),hadSize=dj.contains("size");int oldMode=dj.getInt("mode",0),oldCount=dj.getInt("size",1);SharedPreferences radio=c.getSharedPreferences("radio",0);String[] keys={"catalog","query","city","catalog_city"};Map<String,String> old=new HashMap<>();for(String key:keys)old.put(key,radio.getString(key,null));boolean hadCountry=radio.contains("brazil"),country=radio.getBoolean("brazil",true);List<String> problems=new ArrayList<>();JSONArray screens=new JSONArray();Activity current=null;
  Class<?>[] pages={MainActivity.class,OnlineActivity.class,DownloadsActivity.class,DownloadCenterActivity.class,LocalConverterActivity.class,OndaFilesActivity.class,ImageSearchActivity.class,RadioActivity.class,YouTubeActivity.class,YouTubeFavoritesActivity.class,VideoActivity.class,PdfActivity.class,AppearanceActivity.class,AudioOutputActivity.class,SoundActivity.class,SpeechActivity.class,AudioChaptersActivity.class,BackupActivity.class,UpdateActivity.class,VoicePhrasesActivity.class,QueueActivity.class,PlaylistsActivity.class,SmartLibraryActivity.class,DjActivity.class,ShelfActivity.class,UnifiedSearchActivity.class,LyricsActivity.class,ConnectActivity.class};
  try{if(narrow){shell("wm size 840x1680");shell("wm density 420");Thread.sleep(400);}RadioStation fixture=new RadioStation("layout-audit","Rádio de layout","https://radio.example.org/layout","Brasil","AAC",128,false);RadioStore.cache(c,Collections.singletonList(fixture),"",true);radio.edit().remove("city").putString("catalog_city","").commit();shell("settings put system font_scale 1.3");Thread.sleep(700);
   for(Class<?> type:pages){current=ins.startActivitySync(new Intent(c,type).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));final Activity screen=current;ins.waitForIdleSync();Thread.sleep(250);ins.runOnMainSync(()->{assertFalse(type.getSimpleName()+" unexpectedly closed",screen.isFinishing());assertEquals(1.3f,screen.getResources().getConfiguration().fontScale,.02f);View root=screen.findViewById(android.R.id.content);assertTrue(type.getSimpleName()+" empty layout",root.getWidth()>0&&root.getHeight()>0);inspect(screen,root,problems);ScrollView form=scroll(root);if(type==UpdateActivity.class)assertNotNull("Updates must scroll at large font",form);if(form!=null){form.setSmoothScrollingEnabled(false);form.fullScroll(View.FOCUS_DOWN);}});ins.waitForIdleSync();Thread.sleep(60);ins.runOnMainSync(()->inspect(screen,screen.findViewById(android.R.id.content),problems));if(type==OnlineActivity.class){ins.runOnMainSync(()->{try{java.lang.reflect.Field field=OnlineActivity.class.getDeclaredField("filterPanel");field.setAccessible(true);((View)field.get(screen)).setVisibility(View.VISIBLE);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();Thread.sleep(100);ins.runOnMainSync(()->{ScrollView form=scroll(screen.findViewById(android.R.id.content));if(form!=null)form.scrollTo(0,0);inspect(screen,screen.findViewById(android.R.id.content),problems);});}
   if(type==DjActivity.class){ins.runOnMainSync(()->{try{java.lang.reflect.Field m=DjActivity.class.getDeclaredField("mode"),n=DjActivity.class.getDeclaredField("size");m.setAccessible(true);n.setAccessible(true);((Spinner)m.get(screen)).setSelection(4);((Spinner)n.get(screen)).setSelection(2);}catch(Exception e){throw new RuntimeException(e);}});ins.waitForIdleSync();Thread.sleep(100);ins.runOnMainSync(()->inspect(screen,screen.findViewById(android.R.id.content),problems));}
   if(type==MainActivity.class&&narrow)ins.runOnMainSync(()->{try{java.lang.reflect.Field field=MainActivity.class.getDeclaredField("libraryList");field.setAccessible(true);View list=(View)field.get(screen);if(((View)list.getParent()).getHeight()<Ui.dp(c,48))problems.add("MainActivity: usable library area is smaller than 48dp");}catch(Exception e){throw new RuntimeException(e);}});
   ins.runOnMainSync(()->{View focus=screen.getCurrentFocus();if(focus!=null)focus.clearFocus();ScrollView form=scroll(screen.findViewById(android.R.id.content));if(form!=null)form.scrollTo(0,0);});ins.waitForIdleSync();Thread.sleep(120);
   BitmapCapture.capture(ins,c,type.getSimpleName()+(narrow?"-compact":"-normal"));screens.put(type.getSimpleName());ins.runOnMainSync(screen::finish);ins.waitForIdleSync();current=null;}
   JSONObject report=new JSONObject().put("fontScale",1.3).put("widthDp",c.getResources().getConfiguration().screenWidthDp).put("compact",narrow).put("screens",screens).put("screenCount",screens.length()).put("clippedNativeText",new JSONArray(problems)).put("updatesFormScrolls",true).put("noProductPollingAdded",true);try(OutputStream out=new FileOutputStream(new File(c.getFilesDir(),"screen-layout-review-"+(narrow?"compact":"normal")+".json"))){out.write(report.toString(2).getBytes("UTF-8"));}assertTrue("Clipped native text: "+problems,problems.isEmpty());
  }finally{if(current!=null){Activity screen=current;ins.runOnMainSync(screen::finish);}if(narrow){shell("wm size "+oldSize);shell("wm density "+oldDensity);}shell(oldFont.equals("null")?"settings delete system font_scale":"settings put system font_scale "+oldFont);Thread.sleep(500);SharedPreferences.Editor edit=radio.edit();for(String key:keys)if(old.get(key)==null)edit.remove(key);else edit.putString(key,old.get(key));if(hadCountry)edit.putBoolean("brazil",country);else edit.remove("brazil");edit.commit();SharedPreferences.Editor restore=dj.edit();if(hadMode)restore.putInt("mode",oldMode);else restore.remove("mode");if(hadSize)restore.putInt("size",oldCount);else restore.remove("size");restore.commit();}
 }
}
